            if (ip[0] == 127) return true; // 127.0.0.0/8 (Loopback)
            if (ip[0] == 0) return true; // 0.0.0.0/8
            if (ip[0] == (byte) 169 && ip[1] == (byte) 254) return true; // 169.254.0.0/16 (Link-local)
        } else if (ip.length == 16) {
            if ((ip[0] & (byte) 0xFE) == (byte) 0xFC) return true; // fc00::/7 (Unique Local Address)

            // Check for IPv4-mapped IPv6 addresses (::ffff:x.x.x.x) to prevent bypasses
            if (ip[0] == 0 && ip[1] == 0 && ip[2] == 0 && ip[3] == 0 && 
                ip[4] == 0 && ip[5] == 0 && ip[6] == 0 && ip[7] == 0 &&
                ip[8] == 0 && ip[9] == 0 && ip[10] == (byte) 0xFF && ip[11] == (byte) 0xFF) {
                byte[] ipv4 = new byte[4];
                System.arraycopy(ip, 12, ipv4, 0, 4);
                if (ipv4[0] == 10) return true;
                if (ipv4[0] == (byte) 172 && (ipv4[1] >= 16 && ipv4[1] <= 31)) return true;
                if (ipv4[0] == (byte) 192 && ipv4[1] == (byte) 168) return true;
                if (ipv4[0] == 127) return true;
                if (ipv4[0] == 0) return true;
                if (ipv4[0] == (byte) 169 && ipv4[1] == (byte) 254) return true;
            }
        }
        return false;
    }

    /**
     * Reads the HTTP response stream with a strict size limit to prevent Denial of Service (OOM) attacks.
     */
    private String readLimitedContent(HttpEntity entity, int maxBytes) throws IOException {
        try (InputStream inputStream = entity.getContent()) {
            ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            byte[] data = new byte[8192];
            int nRead;
            int totalRead = 0;
            while ((nRead = inputStream.read(data, 0, data.length)) != -1) {
                totalRead += nRead;
                if (totalRead > maxBytes) {
                    throw new IOException("Response exceeds maximum allowed size of " + maxBytes + " bytes");
                }
                buffer.write(data, 0, nRead);
            }
            return buffer.toString(StandardCharsets.UTF_8.name());
        }
    }
